import axios from "axios";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button1, LoadingButton } from "../components/button";
import {
  BurgerIcon,
  DownloadIcon,
  FingerprintIcon,
  ImageIcon,
  PastLife,
  RocketIcon,
  ServerIcon,
} from "../components/icons";
import { Toast2 } from "../components/toast";

function ControlPage({ private_Date, setSideMenuOpen, activeSideMenu }) {
  const navigate = useNavigate();
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  const xpass = localStorage.getItem("user");
  const raw_pass = JSON.parse(xpass).access;

  const [passw, setPass] = useState(""); //new
  const [passw2, setPass2] = useState(""); //old

  const [centerpassword, setPassword] = useState(raw_pass);

  const [matchBa, setMatchBa] = useState(false);
  const checkMatch = (e) => {
    const tycheck = e.target.value;
    setPass2(tycheck);
    if (tycheck === raw_pass) {
      setMatchBa(true);
      setPassError(false);
    } else {
      setMatchBa(false);
      setPassError("Invalid old password.");
    }
  };

  const [passerror, setPassError] = useState("");
  const createNew = (e) => {
    if (matchBa) {
      setPass(e.target.value);
      setPassword(e.target.value);
      setPassError(false);
    } else {
      setPassError("Please confirm old password first.");
    }
  };

  const [profile, setProfile] = useState(
    private_Date.Profile ||
      "https://kiapifers-dlver.cloud/storage/defaults/default.png"
  );
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setProfile(URL.createObjectURL(file));
    UploadImage(file);
  };

  const [loadup, setUp] = useState(false);
  const UploadImage = async (file) => {
    const data = new FormData();
    data.append("file", file);
    try {
      setUp(true);
      const response = await axios.post(
        "https://kiapifers-dlver.cloud/storage/upload.php",
        data,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );

      if (response.data.success) {
        setUp(false);
        setProfile(response.data.url);
        updateAdmin(response.data.url);
      } else {
        setUp(false);
      }
    } catch (error) {
      setUp(false);
    }
  };

  //console.log(private_Date);

  const updateAdmin = async (imgs) => {
    try {
      const boday = {
        Email: private_Date.Email,
        Profile: imgs,
        // Pass: centerpassword,
        // Name:private_Date.Name,
        // Role:private_Date.Role,
        // Status:private_Date.Status
      };

      const response = await axios.post(
        "https://kiapifers-dlver.cloud/adminconsole/updateadmin/",
        boday,
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      setUp(false);
      showAlert("Profile Updated!");
    } catch (e) {
      console.log(e);
    }
  };

  const [upaway, setApWay] = useState(false);
  const updateAdminInfo = async () => {
    setApWay(true);
    try {
      const boday = {
        Email: private_Date.Email,
        //Profile: private_Date.Profile,
        Password: centerpassword,
        // Name:private_Date.Name,
        // Role: private_Date.Role,
        // Status:private_Date.Status
      };

      const response = await axios.post(
        "https://kiapifers-dlver.cloud/adminconsole/updateadmin/",
        boday,
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      setApWay(false);
      showAlert("Password Changed");
      setPass("");
      setPass2("");
    } catch (e) {
      console.log(e);
      setApWay(false);
    }
  };

  const [allAdmins, setAdmins] = useState([]);
  const [logs, setLogs] = useState([]);
  useEffect(() => {
    const allAdmins = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/adminconsole/pulladmin/",
          {}
        );
        setAdmins(response.data.data);
      } catch (e) {
        console.log(e);
      }
    };

    const allLogs = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/activity/",
          {}
        );
        // console.log(response.data);
        setLogs(response.data);
      } catch (e) {
        console.log(e);
      }
    };

    allLogs();
    allAdmins();
  }, []);

  const changeRole = async (account) => {
    const userAd = account.Email;

    try {
      const boday = {
        Email: userAd,
        // Role: account.Role,
        // Name:account.Name,
        // Profile: account.Profile,
        Status: account.Status == "Active" ? "Disable" : "Active",
      };

      const response = await axios.post(
        "https://kiapifers-dlver.cloud/adminconsole/updateadmin/",
        boday,
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      setAdmins((prevAdmins) =>
        prevAdmins.map((admin) =>
          admin.Email === userAd ? { ...admin, Status: boday.Status } : admin
        )
      );
      showAlert("Status Changed");
    } catch (e) {
      console.log(e);
    }
  };

  const changeAdmin = async (account) => {
    const userAd = account.Email;
    try {
      const boday = {
        Email: userAd,
        Role: account.Role == "Admin" ? "User" : "Admin",
        // Name:account.Name,
        // Status: account.Status,
        // Profile: account.Profile,
      };

      const response = await axios.post(
        "https://kiapifers-dlver.cloud/adminconsole/updateadmin/",
        boday,
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      setAdmins((prevAdmins) =>
        prevAdmins.map((admin) =>
          admin.Email === userAd ? { ...admin, Role: boday.Role } : admin
        )
      );
      showAlert("Status Changed");
    } catch (e) {
      console.log(e);
    }
  };

  const [clearing, setClearing] = useState(false);
  const clearCache = () => {
    setClearing(true);

    showAlert("Please wait..");

    setTimeout(() => {
      // Clear local storage
      localStorage.clear();
      // Clear session storage
      sessionStorage.clear();
      navigate("/login");
      // Reload the page to fetch fresh resources
      window.location.reload(true);
    }, 5000);
  };

  const [selectTab, setTable] = useState(null);
  const selectTable = (e) => {
    setTable(e.target.value);
  };

  const [loadingBackup, setLoadBakup] = useState(false);
  const [fileUrl, setFileUrl] = useState("");
  const executeBackup = async () => {
    try {
      setLoadBakup(true);
      const aUI = {
        Email: private_Date.Email,
        Table: selectTab,
      };

      const response = await axios.post(
        "https://kiapifers-dlver.cloud/backup/dbbackup/",
        aUI
      );
      if (response.data.status === "success") {
        setFileUrl(response.data.fileUrl);
      }

      setLoadBakup(false);
    } catch (e) {
      console.log(e);
      setLoadBakup(false);
    }
  };

  //download admin report
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [loading, setLoading] = useState(false);
  const [dlreport,setDlreport] = useState('')

  // Function to convert Date string to Unix Timestamp
  const toUnixTimestamp = (dateStr) =>
    Math.floor(new Date(dateStr).getTime() / 1000);

  const downloadReport = async () => {
    if (!startDate || !endDate) {
      alert("Please select both start and end dates.");
      return;
    }

    setLoading(true);

    // Convert the selected dates to Unix timestamps
    const StartingDate = toUnixTimestamp(startDate);
    const EndDate = toUnixTimestamp(endDate);
    console.log(StartingDate, EndDate);
    // Build the API URL with the parameters
    const apiUrl = `https://kiapifers-dlver.cloud/report/admin/index.php?=&startingDate=${StartingDate}&endDate=${EndDate}`;

    try {
      const response = await axios.get(apiUrl);
      const data = await response.data;

      if (data.success) {
        // Create a link element to download the file
        const downloadLink = data.downloadLink;
        const anchor = document.createElement("a");
        anchor.href = downloadLink;
        setDlreport(downloadLink)
        anchor.download = "report.xlsx"; // Default file name
        document.body.appendChild(anchor);
        anchor.click();
        document.body.removeChild(anchor);
      } else {
        showAlert(`Ops! ${data.message}`);
      }
    } catch (error) {
      alert(`Failed to download the report: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const downloadFile = () => {
    if (!fileUrl) return;

    // Create a temporary <a> element and trigger a download
    const link = document.createElement("a");
    link.href = fileUrl;

    // Optionally set a download attribute with a filename
    link.download = fileUrl.split("/").pop(); // Use the filename from the URL
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  function timeAgo(timestampInSeconds) {
    // Convert timestamp from seconds to milliseconds
    const timestamp = timestampInSeconds * 1000;

    // Calculate time difference in milliseconds
    const now = Date.now();
    const timeDifference = now - timestamp;

    if (timeDifference < 0) {
      return "In the future"; // Future date case (if applicable)
    }

    if (timeDifference < 60000) {
      // Less than a minute
      return "Just now";
    } else if (timeDifference < 3600000) {
      // Less than an hour
      const minutes = Math.floor(timeDifference / 60000);
      return minutes === 1 ? "a minute ago" : `${minutes} minutes ago`;
    } else if (timeDifference < 86400000) {
      // Less than a day
      const hours = Math.floor(timeDifference / 3600000);
      return hours === 1 ? "1 hour ago" : `${hours} hours ago`;
    } else if (timeDifference < 604800000) {
      // Less than a week
      const days = Math.floor(timeDifference / 86400000);
      return days === 1 ? "Yesterday" : `${days} days ago`;
    } else {
      // More than a week
      const weeks = Math.floor(timeDifference / 604800000);
      return weeks === 1 ? "Last week" : `${weeks} weeks ago`;
    }
  }

  return (
    <div>
      <nav className="block  lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>
      <div className="p-2.5">
        <section className="flex flex-wrap gap-4 w-full">
          <div className="border border-gray-300 p-2.5 rounded-xl shadow-lg bg-white w-96">
            <div>
              <div className="flex justify-center items-center p-2">
                <div
                  className={`relative ${
                    loadup && "animte-pulse"
                  } border-8 border-red-500 h-24 w-24 rounded-full`}
                >
                  <img
                    src={profile}
                    alt=""
                    className="rounded-full w-full h-full"
                  />
                  <div className="rounded-full bg-[#ff1616] border-2 border-white absolute bottom-0 -right-1 flex justify-center items-center p-1.5">
                    <label
                      htmlFor="file-upload"
                      className="bg-transparent cursor-pointer "
                    >
                      <ImageIcon c="#ffff" h="15" w="15" />
                      <input
                        id="file-upload"
                        name="file-upload"
                        type="file"
                        accept="image/*"
                        className="sr-only outline-none cursor-pointer"
                        onChange={handleFileChange}
                      />
                    </label>
                  </div>
                </div>
              </div>
              <div className="text-center pt-2">
                <h1 className="text-lg font-medium">{private_Date.Name}</h1>
                <p className="text-sm font-normal text-gray-500">
                  {private_Date.Role}
                </p>
              </div>
              <div className="p-4">
                <h1>Change Password</h1>
                <input
                  type="text"
                  className="outline-none text-gray-500 border border-gray-300 px-2.5 py-1.5 my-1.5 w-full rounded-lg"
                  value={passw2}
                  onChange={checkMatch}
                  placeholder="Current Password"
                />
                {passerror && (
                  <p className="text-xs my-1.5 text-red-800">{passerror}</p>
                )}
                <input
                  type="text"
                  className="outline-none text-gray-500 border border-gray-300 px-2.5 py-1.5 my-1.5 w-full rounded-lg"
                  value={passw}
                  onChange={createNew}
                  placeholder="New Password"
                />

                {matchBa &&
                  (upaway ? (
                    <LoadingButton />
                  ) : (
                    <Button1 click={updateAdminInfo} text="Save Password" />
                  ))}
              </div>
            </div>
          </div>

          <div className="border border-gray-300 py-2.5 px-4 rounded-xl shadow-lg bg-white w-96">
            <h1 className="font-medium text-lg">Admin Accounts</h1>
            <ul className="overflow-y-auto h-auto max-h-72">
              {allAdmins.map((account) => (
                <li
                  key={account.ftid}
                  className={`flex ${
                    account.Status !== "Active" && "opacity-25"
                  } justify-between items-center p-2.5 space-x-2.5 border-b border-gray-300`}
                >
                  <div className="flex justify-start items-center space-x-2.5">
                    <img
                      src={
                        account.Profile ||
                        "https://kiapifers-dlver.cloud/storage/defaults/default.png"
                      }
                      alt=""
                      className="h-8 w-8 rounded-full"
                    />
                    <div>
                      <p className="font-medium truncate ">{account.Name}</p>
                      <div className="flex justify-start items-center">
                        <FingerprintIcon c="#6b7280" w="13" h="13" />
                        {private_Date.Role === "SuperAdmin" ? (
                          <select
                            name={account.Email}
                            className="appearance-none cursor-pointer outline-none text-gray-600 px-2 rounded-lg text-xs"
                            value={account.Role}
                            onChange={() => changeAdmin(account)}
                          >
                            <option value="User">User</option>
                            <option value="Admin">Admin</option>
                            <option value="SuperAdmin">SuperAdmin</option>
                          </select>
                        ) : (
                          <p className="text-xs ml-1.5 text-gray-500">
                            {account.Role}
                          </p>
                        )}
                      </div>
                    </div>
                  </div>
                  {private_Date.Role === "SuperAdmin" && (
                    <div>
                      <select
                        name={account.Email}
                        className="cursor-pointer outline-none border border-gray-300 px-2 py-0.5 rounded-lg text-xs"
                        value={account.Status}
                        onChange={() => changeRole(account)}
                      >
                        <option value="Active">Active</option>
                        <option value="Disable">Disable</option>
                      </select>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          </div>

          <div className="border border-gray-300 p-4 rounded-xl shadow-lg bg-white w-96">
            <div className="flex justify-start items-center space-x-2.5">
              <PastLife c="#404040" w="30" h="30" />
              <div className="leading-tight">
                <h1 className="text-lg text-gray-600 font-medium">
                  Recent Activity
                </h1>
                <p className="text-gray-500 text-xs leading-tight">
                  Retrack logs.
                </p>
              </div>
            </div>
            <ul className="overflow-y-auto h-auto max-h-72">
              {logs?.map((log) => (
                <li className="text-sm truncate border-b border-gray-300 p-2.5">
                  <div className="flex justify-between items-center">
                    <p className="text-gray-600">{log.content}</p>
                    <p className="bg-slate-100 px-2 py-0.5 rounded-xl font-mono text-slate-600">
                      {log.IP}
                    </p>
                  </div>
                  <p className="text-xs text-gray-500">{timeAgo(log.time)}</p>
                </li>
              ))}
            </ul>
          </div>

          <div className="border border-gray-300 p-4 rounded-xl shadow-lg bg-white w-96">
            <div className="flex justify-start items-center space-x-2.5">
              <ServerIcon c="#404040" w="30" h="30" />
              <div className="leading-tight">
                <h1 className="text-lg font-medium">Backup Resources</h1>
                <p className="text-gray-600 text-xs leading-tight">
                  Manually download data from our database.
                </p>
              </div>
            </div>

            <p className="my-1.5 text-sm text-gray-500">
              Select database to backup first
            </p>

            <div className="flex justify-center items-center space-x-2.5">
              <select
                onChange={selectTable}
                className="w-full cursor-pointer outline-none border-b border-gray-300 px-2.5 py-2.5 text-lg"
              >
                <option value="BOOKING">Booking</option>
                <option value="ADVERTISEMENT">Advertisement</option>
                <option value="MERCHANT">Merchant</option>
                <option value="MERCHANT_PRODUCT">Merchant Product</option>
                <option value="PAYMENT">Payment</option>
                <option value="REVIEW">Reviews</option>
                <option value="RIDER">Riders</option>
                <option value="TRANSACTION">Transactions</option>
                <option value="VOUCHER">Vouchers</option>
              </select>
              {selectTab &&
                (loadingBackup ? (
                  <LoadingButton />
                ) : fileUrl ? (
                  <Button1 click={downloadFile} text="Download CSV" />
                ) : (
                  <Button1 click={executeBackup} text="Run Backup" />
                ))}
            </div>
          </div>

          <div className="border border-gray-300 p-4 rounded-xl shadow-lg bg-white w-96">
            <div className="flex justify-start items-center space-x-2.5">
              <RocketIcon c="#404040" w="30" h="30" />
              <div className="leading-tight">
                <h1 className="text-lg font-medium">Check Panel Updates</h1>
                <p className="text-gray-600 text-xs leading-tight">
                  Your panel version is {process.env.REACT_APP_CONTROL_VERSION}.
                </p>
              </div>
            </div>
            <div className="mt-4">
              {clearing ? (
                <LoadingButton />
              ) : (
                <Button1 click={clearCache} text="Check Over-The-Air Updates" />
              )}
              <p className="text-gray-600 text-xs leading-tight">
                <strong>Note:</strong> By rebooting this panel, it will log-out
                your account and requires re-login.
              </p>
            </div>
          </div>

          <div className="border border-gray-300 p-2.5 rounded-xl shadow-lg bg-white w-96">
            <h1 className="text-lg font-medium">Website Links</h1>
            <ul>
              <li>
                <a
                  href="https://kiefersdelivery.com"
                  target="_blank"
                  className="my-1.5 text-red-500"
                >
                  Business Website:{" "}
                  <span className="underline">https://kiefersdelivery.com</span>
                </a>
              </li>
              <li>
                <a
                  href="https://kiefers-app.com"
                  target="_blank"
                  className="my-1.5 text-red-500"
                >
                  App Hosting:{" "}
                  <span className="underline">https://kiefers-app.com</span>
                </a>
              </li>
            </ul>
          </div>

          <div className="border border-gray-300 p-2.5 rounded-xl shadow-lg bg-white w-96">
            <h1 className="text-lg font-medium">Admin Report</h1>
            <div className="py-2 flex flex-col sm:grid sm:grid-cols-2 sm:gap-2 sm:items-center sm:justify-start space-y-2 sm:space-y-0 ">
              <div>
                <input
                  type="date"
                  className="block w-full rounded-md border-0 py-1.5 text-gray-500 font-medium shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
              </div>
              {startDate && (
                <div>
                  <input
                    type="date"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-500 font-medium shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                  />
                </div>
              )}

              {endDate && (
                <div className="w-full flex justify-between items-center space-x-2.5">
                  <button
                  onClick={downloadReport}
                  disabled={loading}
                  className="sm:col-span-2 flex justify-center items-center space-x-2 border bg-[#ff1616] hover:shadow-lg px-2.5 py-2 rounded-lg"
                >
                  <DownloadIcon c="#fff" w={17} h={17} />{" "}
                  <p className="text-sm text-white">
                    {loading ? "Generating..." : "Download"}
                  </p>
                </button>
                {
                  dlreport != '' && (
                    <div>
                      <span>or <a className="font-medium text-blue-400" href={dlreport} target="_blank" >Download here</a></span>
                      </div>
                  )
                }
                </div>
              )}
            </div>
          </div>
        </section>
        <Toast2 visible={errorShow} message={errormsg} />
      </div>
    </div>
  );
}

export default ControlPage;
