import axios from "axios";
import {
  addDoc,
  collection,
  doc,
  getDoc,
  getDocs,
  getFirestore,
  onSnapshot,
  orderBy,
  query,
  serverTimestamp,
  setDoc,
  where,
} from "firebase/firestore";
import React, { useEffect, useRef, useState } from "react";
import { Button1, ButtonWithIcon } from "../components/button";
import { InboxCard, InboxCard2 } from "../components/cards";
import {
  ArrowLeftBig,
  BotIcon,
  BurgerIcon,
  CloseIcon,
  MagicIcon,
  PlayIcon,
  SoundIcon,
} from "../components/icons";
import { BigGreetingsTitle } from "../components/title";
import { Toast2 } from "../components/toast";
import { Tooltip1 } from "../components/tooltip";

const CHATVIEW = ({ bringAssignee, sourceData, storedUser, roomId }) => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [sending, startSend] = useState(false);
  const [joinIN, setJoinIn] = useState(false);
  const [assignee, setAssignee] = useState(null);
  const [assigneeImage, setAssigneeImage] = useState(null);
  const chatContainerRef = useRef(null);

  const db = getFirestore();

  const [newMessage, setNewMessage] = useState("");

  const [lock, setLock] = useState(false);
  const [handleName, setHandleName] = useState(null);
  const [handleImage, sethandleImage] = useState(null);

  useEffect(() => {
    if (sourceData) {
      if (
        bringAssignee[0].face === storedUser.email &&
        bringAssignee[0].status === true
      ) {
        setJoinIn(true);
      }
    }

    setAssignee(storedUser.email);
    setAssigneeImage(storedUser.profile);

    const chatRoomRef = collection(db, "ChatRooms");
    const agentDocRef = doc(db, "ChatRooms", roomId, "assignee", "keepers0115");

    // Real-time listener for assignee data
    const unsubscribeAssignee = onSnapshot(
      agentDocRef,
      (docSnapshot) => {
        if (docSnapshot.exists()) {
          const assigneeData = docSnapshot.data();
          console.log("Real-time Assignee Data:", assigneeData);

          if (assigneeData.status === true) {
            // Handle assigned case
            setJoinIn(false);
            setLock(true);
            setHandleName(assigneeData.face);
            sethandleImage(assigneeData.image);
            if (assigneeData.face === storedUser.email) {
              setJoinIn(true);
              setLock(true);
            }
          } else {
            // Handle not assigned case
            setJoinIn(false);
            setLock(false);
          }
        } else {
          console.log("No such document!");
          setJoinIn(false);
        }
      },
      (error) => {
        console.error("Error listening to assignee data:", error);
        setJoinIn(false);
      }
    );

    // Real-time listener for messages
    const messagesQuery = query(
      chatRoomRef,
      where("roomId", "==", roomId),
      orderBy("timestamp", "asc")
    );

    const unsubscribeMessages = onSnapshot(messagesQuery, (querySnapshot) => {
      const messagesData = [];
      querySnapshot.forEach((doc) => {
        messagesData.push({ id: doc.id, ...doc.data() });
      });
      setMessages(messagesData || []);
    });

    // Cleanup listeners on component unmount
    return () => {
      unsubscribeAssignee(); // Stop listening to assignee data
      unsubscribeMessages(); // Stop listening to messages
    };
  }, [sourceData, setJoinIn, roomId, db]);

  const handleInputChange = (e) => {
    setInput(e.target.value);
  };

  const handleKeyDown = (event) => {
    if (event.key === "Enter") {
      sendMessage();
    }
  };

  const jointheChat = async () => {
    //disable AI
    //set message
    const messagesRef = collection(db, "ChatRooms");
    // await addDoc(messagesRef, {
    //   role: 'assistant',
    //   content: 'An agent joined the chat',
    //   face: assignee,
    //   timestamp: serverTimestamp()
    // });
    const role = "assistant";
    const content = "An agent joined the chat";
    await addDoc(messagesRef, {
      roomId, // Associate message with the roomId
      role, // user email or role
      content, // message content
      face: assignee,
      timestamp: serverTimestamp(),
      typing: false,
      seen: false,
    });
    await setDoc(doc(db, "Signal", roomId), {
      assistant: false,
    });
    await setDoc(doc(db, "ChatRooms", roomId, "assignee", "keepers0115"), {
      status: true,
      face: assignee,
      image: assigneeImage,
    });

    setJoinIn(true);
  };

  const removeAssignee = async () => {
    //enable ai
    setJoinIn(false);
    const messagesRef = collection(db, "ChatRooms");
    // await addDoc(messagesRef, {
    //   role: 'assistant',
    //   content: 'Agent left the chat',
    //   face: assignee,
    //   timestamp: serverTimestamp()
    // });
    const role = "assistant";
    const content = "Agent left the chat";
    await addDoc(messagesRef, {
      roomId, // Associate message with the roomId
      role, // user email or role
      content, // message content
      face: assignee,
      timestamp: serverTimestamp(),
      typing: false,
      seen: false,
    });

    await setDoc(doc(db, "Signal", roomId), {
      assistant: true,
    });
    await setDoc(doc(db, "ChatRooms", roomId, "assignee", "keepers0115"), {
      status: false,
      face: assignee,
      image: assigneeImage,
    });
  };

  const sendMessage = async () => {
    if (input.trim() === "") {
      return;
    }
    startSend(true);

    const messagesRef = collection(db, "ChatRooms");
    // await addDoc(messagesRef, {
    //   role: 'Agent',
    //   content: input, // Replace with actual sender's email
    //   timestamp: serverTimestamp()
    // });
    const role = "Agent";
    const content = input;
    await addDoc(messagesRef, {
      roomId, // Associate message with the roomId
      role, // user email or role
      content, // message content
      timestamp: serverTimestamp(),
      typing: false,
      seen: false,
    });

    setInput("");
    startSend(false);
  };

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop =
        chatContainerRef.current.scrollHeight;
    }
  }, [messages]);

  return (
    <div className="px-2.5 bg-white">
      <div
        ref={chatContainerRef}
        className="w-full bg-gray-50 h-96 max-h-[76vh] overflow-y-auto p-2 border border-gray-300 rounded-lg"
      >
        {messages.map((msg, index) =>
          msg.content === "An agent joined the chat" ||
          msg.content === "Agent left the chat" ? (
            <div className="w-full flex space-x-2.5 justify-center h-12 items-center text-center text-gray-400 text-sm">
              <span className="w-96 h-px bg-gray-200"></span>
              <p>
                {msg.content} - {msg.face}
              </p>
              <span className="w-96 h-px bg-gray-200"></span>
            </div>
          ) : (
            <div
              key={index}
              className={
                msg.role === "user" ||
                msg.role == "assistant" ||
                msg.role == "Agent"
                  ? "flex justify-end"
                  : "flex justify-start"
              }
            >
              <div
                className={
                  msg.role === "user" ||
                  msg.role == "assistant" ||
                  msg.role == "Agent"
                    ? "bg-[#ff1616] text-white m-2 rounded-lg p-2"
                    : "bg-gray-200 text-gray-800 m-2 rounded-lg p-2"
                }
              >
                {msg.role == "assistant" && (
                  <div className="flex justify-start items-center space-x-0.5">
                    <BotIcon c="#fff" w="20" h="20" />
                    <p className="text-xs text-red-100">Assistant</p>
                  </div>
                )}
                <p>{msg.content}</p>
              </div>
            </div>
          )
        )}
      </div>
      {joinIN ? (
        <>
          <div className="mt-2.5 flex justify-start items-center space-x-2.5 w-auto">
            <div className="border border-gray-300 p-2 rounded-lg relative flex justify-start items-center space-x-2.5 ">
              <img
                src={assigneeImage}
                alt=""
                class="object-cover h-12 w-12 rounded-full"
              />
              <div>
                <p className="font-medium text-lg">Assigned</p>
                <p className="font-normal text-gray-500 text-sm">{assignee}</p>
              </div>

              {storedUser.email === assignee && (
                <div
                  onClick={removeAssignee}
                  className="border border-gray-300 cursor-pointer hover:bg-gray-300 bg-gray-200 p-1 rounded-full shadow-lg absolute -top-2 -right-2"
                >
                  <CloseIcon c="#404040" w="15" h="15" />
                </div>
              )}
            </div>
          </div>
          <div className="mt-2.5 w-full flex justify-between h-auto">
            <div className="w-full flex space-x-2.5 py-2.5">
              <input
                type="text"
                value={input}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
                placeholder="Enter your message"
                className="bg-gray-100 p-4 rounded-lg w-full outline-none border-none"
                readOnly={sending ? true : false}
              />
              {sending ? (
                <button className="bg-slate-200 font-medium px-2 py-1.5 rounded-lg text-white">
                  Sending..
                </button>
              ) : (
                <button
                  onClick={sendMessage}
                  className={` ${
                    input
                      ? "bg-[#ff1616] text-white"
                      : "bg-slate-100 text-gray-600"
                  } hover:bg-[#ff1616] px-2.5 py-0.5 rounded-lg hover:text-white w-48`}
                >
                  Send
                </button>
              )}
            </div>
          </div>
        </>
      ) : (
        <div className="mt-2.5 w-full flex justify-center h-full bg-white">
          <div className="w-96 flex justify-center space-x-2.5 py-2.5">
            {lock ? (
              <div className="border border-gray-300 rounded-lg flex justify-center items-center text-center py-2 px-4 space-x-2.5">
                <div className="mb-2.5">
                  <h1 className="text-md text-gray-500 font-medium">
                    Handled now by:
                  </h1>
                  <p className="text-sm text-gray-600">{handleName}</p>
                  <p className="bg-yellow-100 text-yellow-600 rounded-lg px-2 py-0.5 my-1.5 text-sm">
                    Read-only
                  </p>
                </div>
                <div className="flex justify-center items-center space-x-4 ">
                  <img
                    src={handleImage}
                    alt=""
                    class="border border-gray-300 object-cover h-16 w-16 rounded-full"
                  />
                </div>
              </div>
            ) : (
              <div className="w-full text-center p-2">
                <h1 className="text-xl font-medium mb-2.5">
                  Do you want to join the chat?
                </h1>
                <div className="flex justify-center items-center space-x-4 w-full ">
                  <img
                    src={assigneeImage}
                    alt=""
                    class="shadow-lg object-cover h-12 w-12 rounded-full"
                  />
                  <Tooltip1 text="Clicking this button will join you in the user chat and disable the AI chat, also by leaving the chat will bring AI Chat to response. Make sure you are ready.">
                    <Button1 text="Join Chat" click={jointheChat} />
                  </Tooltip1>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// Define your chat components separately
const AICHAT = ({ storedUser }) => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [sending, startSend] = useState(false);
  var menu;
  const chatContainerRef = useRef(null);

  const handleInputChange = (e) => {
    setInput(e.target.value);
  };

  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 2000);
  };

  const [trainingText, setTraining] = useState("");
  const [trainingExpand, setTrainExpand] = useState(
    storedUser.role === "User" ? false : true
  );

  useEffect(() => {
    const pullHistory = async () => {
      try {
        const response = await axios.post(process.env.REACT_APP_PULL_HISTORY, {
          uid: storedUser.email,
        });

        //console.log(response.data)
        setMessages(response.data.slice(2) || []);
      } catch (e) {
        //no history
      }
    };

    const pullTraining = async () => {
      try {
        const response = await axios.post(
          "https://kiapifers-dlver.cloud/admin/pull-training/",
          {
            uid: storedUser.email,
          }
        );

        setTraining(response.data);
      } catch (e) {
        //no history
      }
    };

    pullHistory();
    pullTraining();
  }, []);

  const sendMessage = async () => {
    if (input.trim() === "") {
      return;
    }
    startSend(true);
    try {
      const response = await axios.post(process.env.REACT_APP_CHAT_AI_API, {
        message: input,
        myname: storedUser.name,
        uid: storedUser.email,
      });

      const botResponse = response.data.response;
      menu = response.data.menu;

      setMessages([
        ...messages,
        { role: "user", content: input },
        { role: "assistant", content: botResponse },
      ]);

      if (menu) {
        setMessages([
          ...messages,
          { role: "user", content: input },
          { role: "assistant", content: botResponse },
          { role: "assistant", content: JSON.stringify(menu) },
        ]);
      }

      setInput("");
      startSend(false);
    } catch (error) {
      console.error(error);
      startSend(false);
    }
  };

  const detectJSONorPlainText = (input) => {
    try {
      const parsed = JSON.parse(input);

      // Check if parsed result is an array
      if (Array.isArray(parsed)) {
        return true;
      }
    } catch (e) {
      // Parsing failed, so it's plain text
    }

    return false;
  };

  const handleKeyDown = (event) => {
    if (event.key === "Enter") {
      sendMessage();
    }
  };

  const [startTraining, setStartTraining] = useState(false);
  const sendTraining = async () => {
    setStartTraining(true);
    try {
      const response = await axios.post(
        "https://kiefers-app.com/chat/update.php",
        {
          content: trainingText,
        }
      );
      showAlert("Training prompt applied!");
      setStartTraining(false);
    } catch (e) {
      //no history
      console.log(e.error);
      setStartTraining(false);
    }
  };

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop =
        chatContainerRef.current.scrollHeight;
    }
  }, [messages]);

  return (
    <div className="px-2.5">
      <div className="flex space-x-2.5">
        <main className="w-full">
          <div
            ref={chatContainerRef}
            className="w-full bg-white h-[450px] max-h-[96vh] overflow-y-auto p-2 border border-gray-300 rounded-lg"
          >
            {messages.map((msg, index) => (
              <div
                key={index}
                className={
                  msg.role === "user"
                    ? "flex justify-end"
                    : "flex justify-start"
                }
              >
                {detectJSONorPlainText(msg.content) ? (
                  <div>
                    {JSON.parse(msg.content).map((food, ilan) => (
                      <div
                        key={ilan}
                        className="relative bg-white rounded-lg w-full p-2 my-1.5 flex border border-gray-300 justify-start items-center  space-x-2.5"
                      >
                        <div>
                          <img
                            src={food.Image}
                            alt=""
                            className="rounded-lg w-16 h-16"
                          />
                        </div>
                        <div className="w-48">
                          <p className="font-medium text-md">{food.Title}</p>
                          <p className="font-normal text-gray-500 text-xs">
                            {food.Description}
                          </p>
                          <p className="font-normal text-red-600 text-sm">
                            &#8369;{food.Price}{" "}
                            <span className="text-gray-600">
                              - {food.Product}
                            </span>
                          </p>
                          <p className="m-1.5 bg-yellow-100 text-yellow-800 rounded-lg px-2 py-0.5 text-center text-xs">
                            Markup not included
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div
                    className={
                      msg.role === "user"
                        ? "bg-[#ff1616] text-white m-2 rounded-lg p-2"
                        : "bg-gray-200 text-gray-800 m-2 rounded-lg p-2 w"
                    }
                  >
                    <p className="whitespace-pre-line">{msg.content}</p>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="mt-2.5 w-full flex justify-between h-auto">
            <div className="w-full flex space-x-2.5 py-2.5">
              <input
                type="text"
                value={input}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
                placeholder="Type your message"
                className="bg-white p-4 rounded-lg w-full outline-none border-none"
                readOnly={sending ? true : false}
              />
              {sending ? (
                <button className="bg-slate-200 font-medium px-2 py-1.5 rounded-lg text-gray-600">
                  Generating..
                </button>
              ) : (
                <button
                  onClick={sendMessage}
                  className={` ${
                    input
                      ? "bg-[#ff1616] text-white"
                      : "bg-slate-100 text-gray-600"
                  } hover:bg-[#ff1616] px-2.5 py-0.5 rounded-lg hover:text-white w-48`}
                >
                  Send
                </button>
              )}
            </div>
          </div>
        </main>
        {trainingExpand && (
          <div className="p-4 border border-gray-300 rounded-lg w-2/4">
            <div className="w-full">
              <div className="flex justify-between items-center">
                <div className="flex justify-start items-center space-x-2">
                  <BotIcon c="#404040" w="20" h="20" />
                  <p className="text-lg">Training Prompt File</p>
                </div>
                <div
                  onClick={() => setTrainExpand(false)}
                  className="cursor-pointer hover:bg-red-100 p-2 rounded-xl"
                >
                  <CloseIcon c="#404040" w="20" h="20" />
                </div>
              </div>
              <div>
                <textarea
                  rows={15}
                  className="text-sm my-4 px-2 py-2.5 w-full bg-white border border-gray-300 outline-none rounded-lg"
                  value={trainingText}
                  style={{ resize: "none" }}
                  autoComplete="off"
                  autoCorrect="off"
                  onChange={(e) => setTraining(e.target.value)}
                  maxLength={2000}
                  readOnly={storedUser.role === "User" ? true : false}
                />

                {startTraining ? (
                  <div className="bg-slate-300 text-white px-2.5 py-2 rounded-lg w-full flex justify-center items-center">
                    <div className="h-8 w-8 border-2 border-dashed border-white animate-spin border-t-transparent rounded-full"></div>
                  </div>
                ) : storedUser.role != "User" ? (
                  <button
                    onClick={sendTraining}
                    className={` ${
                      trainingText
                        ? "bg-slate-800 text-white"
                        : "bg-slate-100 text-gray-600"
                    } hover:bg-yellow-500 px-2.5 py-2 rounded-lg hover:text-white w-full`}
                  >
                    Start Training
                  </button>
                ) : (
                  <div className=" px-2.5 py-2 rounded-lg bg-gray-300 text-gray-500 cursor-not-allowed w-full text-center">
                    Only Admin can train
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
      <div className="flex justify-center items-center">
        <p className="text-center text-xs text-gray-500 mb-2.5">
          <b>Chai</b> still can make a mistake and still beta. Kiefers dev team
          still training this AI model.
        </p>
        <button
          onClick={() => setTrainExpand(true)}
          className="text-center text-xs text-gray-600 ml-1.5 mb-2.5"
        >
          Want to train Chai?{" "}
          <span className="underline text-gray-800">Start here</span>
        </button>
      </div>
      <Toast2 visible={errorShow} message={errormsg} />
    </div>
  );
};

const USERAICHAT = ({
  setRoom,
  setAScreen,
  setUserInbox,
  setSourceData,
  setAssigneeValue,
  whoChat,
}) => {
  const [chatRooms, setChatRooms] = useState([]);
  const db = getFirestore();

  useEffect(() => {
    const getAssignee = async (gc) => {
      const agentDocRef = doc(db, "ChatRooms", gc, "assignee", "keepers0115");
      try {
        const docSnapshot = await getDoc(agentDocRef);
        if (docSnapshot.exists()) {
          const assigneeData = docSnapshot.data();
          //console.log('Assignee Data:', assigneeData);
          return assigneeData; // Return the fetched assignee data
        } else {
          console.log("No such document!");
          return null; // Return null if no assignee data is found
        }
      } catch (error) {
        console.error("Error fetching assignee data:", error);
        return null; // Return null if there's an error
      }
    };

    const fetchChatRooms = async () => {
      try {
        // Query the ChatRooms collection
        const chatRoomsRef = collection(db, "ChatRooms");
        const chatRoomsSnapshot = await getDocs(chatRoomsRef);

        // Map through each room and include its data, roomId, latest message, and assignee
        const rooms = await Promise.all(
          chatRoomsSnapshot.docs.map(async (doc) => {
            const roomData = doc.data();
            const roomId = doc.id;

            // Fetch the assignee data for each room
            const assigneeData = await getAssignee(roomData.roomId);

            // Return room data with the latest message and assignee data
            return {
              roomId,
              ...roomData,
              assigneeData,
            };
          })
        );

        // Use Set to remove duplicate roomIds and keep the latest data for each room
        const uniqueRooms = [
          ...new Map(rooms.map((room) => [room.roomId, room])).values(),
        ];

        setChatRooms(uniqueRooms); // Set the state with the unique rooms
        console.log("inbox", uniqueRooms); // To see the structure of the rooms and messages
      } catch (error) {
        console.error("Error fetching chat rooms:", error);
      }
    };

    fetchChatRooms();
  }, [db]);

  const OpenChat = (inbox_data) => {
    setAScreen("OPENCHAT");
    setUserInbox(inbox_data.roomId);
    setSourceData(inbox_data);
    setRoom(inbox_data.roomId);
    setAssigneeValue("sdsd");
  };

  return (
    <div className="max-h-[76vh] overflow-y-auto">
      <div>
        {chatRooms.length === 0 && (
          <div className="flex justify-center items-center p-8">
            <div className="border-4 border-gray-300 border-t-transparent h-12 w-12 rounded-full animate-spin"></div>
          </div>
        )}

        <ul>
          {chatRooms.length > 0 ? (
            chatRooms.map((room, index) => (
              <li key={index}>
                {/* Passing assignees data (if exists) or setting it as null */}
                <InboxCard
                  whoChat={whoChat}
                  email={room.roomId}
                  press={() => OpenChat(room)}
                  role={room.role}
                  message={room.content}
                  extra={
                    room.assigneeData ? room.assigneeData : { status: false }
                  } // Pass assignees or null if not available
                />
              </li>
            ))
          ) : (
            <div className="flex justify-center items-center p-8">
              <p className="text-xl text-gray-400">No chat rooms available.</p>
            </div>
          )}
        </ul>
      </div>
    </div>
  );
};

const RIDERCHAT = ({ setAScreen, setUserInbox, setSourceData }) => {
  const allchats = []; //InboxRider();
  const db = getFirestore();
  const OpenChat = (inbox_data) => {
    setAScreen("OPENCHAT");
    setUserInbox(inbox_data.email);
    setSourceData(inbox_data);
  };

  useEffect(() => {
    // Fetch chat rooms from Firestore
    const fetchChatRooms = async () => {
      try {
        // Step 1: Fetch all chat rooms from the 'book' collection
        const querySnapshot = await getDocs(collection(db, "book"));

        const rooms = await Promise.all(
          querySnapshot.docs.map(async (doc) => {
            // Step 2: Check if the room has a 'messages' subcollection
            const messagesCollectionRef = collection(
              db,
              "book",
              doc.id,
              "messages"
            );

            // Fetch the messages if the subcollection exists
            const messagesSnapshot = await getDocs(messagesCollectionRef);

            // If there are no messages, skip adding the messages array
            if (!messagesSnapshot.empty) {
              const messages = messagesSnapshot.docs.map((messageDoc) => ({
                id: messageDoc.id,
                ...messageDoc.data(),
              }));

              return {
                id: doc.id,
                ...doc.data(),
                messages, // Attach messages to the room if available
              };
            } else {
              return {
                id: doc.id,
                ...doc.data(),
                messages: [], // If no messages, set to an empty array
              };
            }
          })
        );

        console.log(rooms); // Now rooms will contain both room data and their respective messages
      } catch (error) {
        console.error("Error fetching chat rooms and messages: ", error);
      }
    };

    fetchChatRooms();
  }, []);

  return (
    <div className="max-h-[76vh] overflow-y-auto">
      <div>
        {allchats.length === 0 && (
          <div>
            <div className="flex justify-center items-center p-8">
              <p className="text-xl text-gray-300">No chat available</p>
            </div>
          </div>
        )}

        {allchats.map((inbox) => (
          <InboxCard2
            press={() => OpenChat(inbox)}
            id={inbox.id}
            email={inbox.email}
            message={inbox.message}
            status={inbox.status}
          />
        ))}
      </div>
    </div>
  );
};

const InboxPage = ({
  whoChat,
  storedUser,
  setSideMenuOpen,
  activeSideMenu,
}) => {
  const [activeScreen, setAScreen] = useState("AICHAT"); // Default screen
  const [userInbox, setUserInbox] = useState("");
  const [sourceData, setSourceData] = useState(null);
  const [roomId, setRoom] = useState(null);
  const [bringAssignee, setAssigneeValue] = useState([]);

  const [playsound, setPlay] = useState(false);

  const testSound = () => {
    setPlay(true);
    const audio = new Audio(
      "https://kiefers-app.com/assets/sounds/new_sound.mp3"
    );

    // Play the sound
    audio.play().catch((error) => console.error("Error playing sound:", error));

    // Detect when the sound has finished playing
    audio.addEventListener("ended", () => {
      setPlay(false);
    });
  };

  const changeView = (screen) => {
    setAScreen(screen);
  };

  const renderScreen = () => {
    switch (activeScreen) {
      case "RIDERCHAT":
        return (
          <RIDERCHAT
            setSourceData={setSourceData}
            setUserInbox={setUserInbox}
            setAScreen={setAScreen}
          />
        );
      case "AICHAT":
        return (
          <USERAICHAT
            whoChat={whoChat}
            setAssigneeValue={setAssigneeValue}
            setRoom={setRoom}
            setSourceData={setSourceData}
            setUserInbox={setUserInbox}
            setAScreen={setAScreen}
          />
        );
      case "OPENCHAT":
        return (
          <CHATVIEW
            bringAssignee={bringAssignee}
            sourceData={sourceData}
            storedUser={storedUser}
            roomId={roomId}
          />
        );
      default:
        return <AICHAT storedUser={storedUser} />;
    }
  };

  return (
    <div className="bg-slate-100 h-full">
      <nav className="block  lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>

      <div className="px-4 pt-8 bg-white h-auto">
        <div className="flex justify-between items-center">
          <div className="flex justify-between space-x-2.5 items-center">
            <BigGreetingsTitle text="Inbox" />
          </div>
          <div
            onClick={testSound}
            className="cursor-pointer flex justify-center items-center space-x-2.5"
          >
            {playsound ? (
              <SoundIcon c="#f87171" w="20" h="20" />
            ) : (
              <PlayIcon c="#404040" w="20" h="20" />
            )}

            {playsound ? <p>Playing..</p> : <p>Test Sound</p>}
          </div>
        </div>
        <section className="mt-2 border border-gray-300 rounded-lg h-auto">
          <div className="px-4 py-2 flex justify-between items-center">
            {activeScreen === "OPENCHAT" ? (
              <div>
                <div
                  onClick={() => changeView("AICHAT")}
                  className="flex space-x-2.5 justify-start items-center cursor-pointer"
                >
                  <ArrowLeftBig c="#404040" h="18" w="18" />
                  <p className="font-medium text-xl">{userInbox}</p>
                </div>
              </div>
            ) : (
              <div className="flex justify-start items-center space-x-4">
                <button
                  onClick={() => changeView("AICHAT")}
                  className={`${
                    activeScreen === "AICHAT"
                      ? "bg-red-100 text-red-600"
                      : "bg-white text-gray-700"
                  } p-2.5 font-normal hover:font-medium rounded-lg`}
                >
                  AI Chats
                </button>
                <button
                  onClick={() => changeView("RIDERCHAT")}
                  className={`${
                    activeScreen === "RIDERCHAT"
                      ? "bg-red-100 text-red-600"
                      : "bg-white text-gray-700"
                  } p-2.5 font-normal hover:font-medium rounded-lg`}
                >
                  Rider Chats
                </button>
              </div>
            )}

            <span className="hidden sm:block">
              <ButtonWithIcon
                press={() => changeView("CHAI")}
                children={<MagicIcon c="#dc2626" w="18" h="18" />}
                title="Talk with Chai AI"
              />
            </span>
          </div>
          {renderScreen()}
        </section>
      </div>

      <span className="block sm:hidden absolute bottom-5 right-5">
        <ButtonWithIcon
          press={() => changeView("CHAI")}
          children={<MagicIcon c="#dc2626" w="18" h="18" />}
          title="Talk with Chai AI"
        />
      </span>
    </div>
  );
};

export default InboxPage;
