import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import { BurgerIcon } from '../components/icons';
import { BigGreetingsTitle } from '../components/title';

const BookingChart = ({ private_Date }) => {
  const [bookingData, setBookingData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [activeSideMenu, setSideMenuOpen] = useState(false);

  // Fetch data when start and end dates change
  useEffect(() => {
    if (startDate && endDate) {
      fetchData();
    }
  }, [startDate, endDate]);

  const fetchData = async () => {
    setLoading(true);

    // Convert dates to timestamp if required by the API
    const startTimestamp = new Date(startDate).getTime() / 1000;
    const endTimestamp = new Date(endDate).getTime() / 1000;

    try {
      const response = await axios.get(
        `https://kiapifers-dlver.cloud/report/totalx/index.php?MerchantID=${private_Date.MerchantID}&StartDate=${startTimestamp}&EndDate=${endTimestamp}`
      );

      if (response.data.success) {
        const formattedData = formatChartData(response.data.bookings);
        setBookingData(formattedData);
      } else {
        console.error("Failed to fetch booking data");
      }
    } catch (error) {
      console.error("Error fetching booking data:", error);
    } finally {
      setLoading(false);
    }
  };

  const formatChartData = (bookings) => {
    const data = [
      ['Date', 'Completed', 'INA', 'MC', 'Cancelled', 'Schedule'], // Column headers for Google Chart
    ];

    bookings.forEach((booking) => {
      const date = booking.bookingDateStart || booking.bookingDate;
      const completedCount = booking.statusDetails.find(status => status.status === 'Completed')?.totalBookings || 0;
      const inaCount = booking.statusDetails.find(status => status.status === 'INA')?.totalBookings || 0;
      const mcCount = booking.statusDetails.find(status => status.status === 'MC')?.totalBookings || 0;
      const cancelledCount = booking.statusDetails.find(status => status.status === 'Cancelled')?.totalBookings || 0;
      const scheduleCount = booking.statusDetails.find(status => status.status === 'Schedule')?.totalBookings || 0;

      data.push([date, completedCount, inaCount, mcCount, cancelledCount, scheduleCount]);
    });

    return data;
  };

  const options = {
    title: 'Booking Status by Date',
    hAxis: { title: 'Date' },
    vAxis: { title: 'Number of Bookings' },
    isStacked: true,
    colors: ['#4CAF50', '#FFC107', '#FF5722', '#F44336', '#2196F3'],
    viewWindow: {
      min: 0,
      max: 10,
    },
  };

  return (
    <div className="bg-white">
      {/* Navbar */}
      <nav className="block lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>

      <div className="p-6">
        <BigGreetingsTitle text="Booking Insights" />

        {/* Date Inputs */}
        <div className="my-2 flex justify-start items-center space-x-2">
          <label>
            Start Date:
            <input
              className="block w-full rounded-md border-0 py-1.5 text-gray-500 font-medium shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
          </label>
          <label>
            End Date:
            <input
              className="block w-full rounded-md border-0 py-1.5 text-gray-500 font-medium shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
            />
          </label>
        </div>

        {/* Loading and Chart */}
        {loading ? (
          <p>Loading booking data...</p>
        ) : bookingData.length > 1 ? (
          <div className="border border-gray-300 rounded shadow-lg">
            <Chart
              chartType="ComboChart"
              width="100%"
              height="400px"
              data={bookingData}
              options={options}
            />
          </div>
        ) : (
          <p className="my-2">No booking data available for the selected dates.</p>
        )}
      </div>
    </div>
  );
};

export default BookingChart;
