import React, { useEffect, useState } from "react";
import { Route, Routes, useNavigate } from "react-router-dom";
import { SideMenu } from "../components/sidebar";
import { Toast2 } from "../components/toast";
import { SessionCheck } from "../config/functions";
import "../scroll.css";
import AdsPage from "./ads";
import CategoryPage from "./categorypage";
import BookingChart from "./charts";
import ControlPage from "./control";
import CouponPage from "./coupons";
import FeedbackPage from "./feedbacks";
import InboxPage from "./inbox";
import LogoutPage from "./logout";
import MapTracker from "./map";
import MerchantPage from "./merchant";
import OverviewPage from "./overview";
import PaymentPage from "./payments";
import RiderPage from "./riderpage";
import UsersPage from "./userspage";

function HomePage({ whoChat, chatOpen, private_Date, onLogout }) {
  const navigate = useNavigate();
  const [privateData, setPriData] = useState([]);
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  useEffect(() => {
    const pullData = localStorage.getItem("user") || [];
    const Token = localStorage.getItem("token") || null;
    const storedUser = JSON.parse(pullData);
    if (!storedUser && Token !== storedUser.session) {
      navigate("/login");
    }
    const AuthMe = async () => {
      const updata = await SessionCheck(Token);
      if (!updata) {
        showAlert("Session expired. Re-login your account again.");
        navigate("/login");
      }
      setPriData(updata);
    };

    if (!private_Date.MerchantID) {
      AuthMe();
    } else {
      setPriData(private_Date);
    }
  }, []);

  const [sideMenuOpen, setSideMenuOpen] = useState(false);

  return (
    <div className="select-none flex h-screen antialiased bg-red-50">
      <div className="hidden lg:block">
        <SideMenu
          chatOpen={chatOpen}
          setSideMenuOpen={setSideMenuOpen}
          storedUser={privateData}
        />
      </div>

      {sideMenuOpen && (
        <SideMenu
          chatOpen={chatOpen}
          setSideMenuOpen={setSideMenuOpen}
          storedUser={privateData}
        />
      )}
      <div className="relative w-full z-auto overflow-x-hidden dark:bg-gray-800">
        <Routes>
          <Route
            path="/"
            element={
              <OverviewPage
                private_Date={private_Date}
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="merchant"
            element={
              <MerchantPage
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
                private_Date={private_Date}
              />
            }
          />
          <Route path="merchant" element={<FeedbackPage />} />
          <Route
            path="rider"
            element={
              <RiderPage
                private_Date={private_Date}
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="users"
            element={
              <UsersPage
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="inbox"
            element={
              <InboxPage
                whoChat={whoChat}
                storedUser={privateData}
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="insights"
            element={<BookingChart private_Date={private_Date} />}
          />
          <Route
            path="tracker"
            element={
              <MapTracker
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="control"
            element={
              <ControlPage
                private_Date={private_Date}
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route path="logout" element={<LogoutPage onLogout={onLogout} />} />
          <Route
            path="ads"
            element={
              <AdsPage
                storedUser={privateData}
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="payments"
            element={
              <PaymentPage
                storedUser={privateData}
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="coupon"
            element={
              <CouponPage
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
          <Route
            path="category"
            element={
              <CategoryPage
                setSideMenuOpen={setSideMenuOpen}
                activeSideMenu={sideMenuOpen}
              />
            }
          />
        </Routes>
      </div>

      <Toast2 visible={errorShow} message={errormsg} />
    </div>
  );
}

export default HomePage;
