export const SideBarMenu = (props) => {
  const location = useLocation();
  const isCurrentPage = location.pathname === props.link;
  return (
    <NavLink onClick={() => props.setSideMenuOpen(false)} to={props.link}>
      <ul
        className={`${
          isCurrentPage ? "bg-[#ff1616]" : "bg-white"
        } w-80 lg:w-auto md:w-auto my-1.5 p-2.5 flex justify-start items-center space-x-2  group hover:bg-[#ff1616] rounded-lg cursor-pointer`}
      >
        {props.children}

        <p
          className={`${
            isCurrentPage ? "text-white" : "text-gray-700"
          } font-medium group-hover:text-white `}
        >
          {props.text}
        </p>
      </ul>
    </NavLink>
  );
};

