import React from "react";
import { BigGreetingsTitle,SubTitle } from "../components/title";
import { CodeTextbox} from "../components/inputs";
import { ButtonGo,Button2} from "../components/button";
import { useNavigate } from 'react-router-dom';



function VerifyPage() {


  const navigate = useNavigate();

  const merchantVerify = ()=>{
    navigate('/home')
  }



  return (
    <div className="max-w-6xl mx-auto px-8 flex justify-center items-center bg-white h-screen w-screen">
      <>
      
      <div className="w-full lg:w-1/2 md:w-1/2 p-2.5 w-full px-12">
        
      <div className="text-center">
      <BigGreetingsTitle text="Verify OTP" />
      <div>
        <CodeTextbox />
      </div>
      <SubTitle text="We sent 6-digits code to your email. This process is one-time only." />
      </div>
     <div className="my-4">
     <ButtonGo click={merchantVerify} text="Continue" />
     <Button2 text="Request New Code" />
     </div>
      </div>
      
      </>
    </div>
  );
}

export default VerifyPage;
