function convertTimestampToReadableDate(timestamp) {
  // Convert the timestamp (seconds) to milliseconds
  const date = new Date(timestamp * 1000);

  // Format the date to a readable format
  return date.toLocaleString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true, // This will use a 12-hour format
  });
}

